#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
set -eu
cd "$(dirname "$0")"
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ -e images/almalinux-8.10-arm64-oci ] || "$F" docker.io/library/almalinux sha256:29fdedeed8a6707558c9e03b5d3e8f09eac5307cdd0811218d7d55a2cc9ae522 almalinux:8.10 images/almalinux-8.10-arm64-oci
[ -f images/almalinux-8.10-amd64.docker.tar ] || "$F" docker.io/library/almalinux sha256:1965cb10f9c392766b2d544d3c1b997eb008d0e413c808e6a20086e87c802a80 almalinux:8.10 images/almalinux-8.10-amd64.docker.tar
ls -ld images/almalinux-8.10-amd64.docker.tar images/almalinux-8.10-arm64-oci
